import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Agents / ACP","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/acp.md","filePath":"zh/guides/acp.md","lastUpdated":1790952322000}'),n={name:"zh/guides/acp.md"};function d(s,e,l,i,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="agents-acp" tabindex="-1">Agents / ACP <a class="header-anchor" href="#agents-acp" aria-label="Permalink to &quot;Agents / ACP&quot;">​</a></h1><p>Memoh 可以把 Bot 连接到 ACP 兼容的编码智能体。ACP 智能体是外部编码工作流，可以从 Bot 的聊天 workspace 里工作，同时把自己的会话和普通 chat / discuss 分开。</p><p>内置两个 agent profile：<strong>Codex</strong>、<strong>Claude Code</strong>。它们是当前支持的配置路径，不代表未来只能接这三种。</p><p>ACP 智能体在 Bot 的容器 workspace 里运行，所以 Bot 必须使用容器类 workspace backend。</p><hr><h2 id="设置流程" tabindex="-1">设置流程 <a class="header-anchor" href="#设置流程" aria-label="Permalink to &quot;设置流程&quot;">​</a></h2><ol><li>打开 Bot<strong>详情页</strong> → <strong>Agents</strong> tab。</li><li>每个智能体一行，右侧 Switch 启用，点行进设置。</li><li>选 setup 模式，按要求填字段。</li><li>保存，然后从聊天 workspace 启动。</li></ol><p>每行有三种状态：<strong>Needs setup</strong>（已启用但缺凭据）、<strong>Disabled</strong>、绿点（就绪）。</p><h3 id="各智能体的-setup-模式" tabindex="-1">各智能体的 Setup 模式 <a class="header-anchor" href="#各智能体的-setup-模式" aria-label="Permalink to &quot;各智能体的 Setup 模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>智能体</th><th>API Key</th><th>OAuth</th><th>Self-managed</th></tr></thead><tbody><tr><td><strong>Codex</strong></td><td>✅</td><td>✅ ChatGPT 登录（设备码）</td><td>✅</td></tr><tr><td><strong>Claude Code</strong></td><td>✅</td><td>✅ 粘贴 <code>claude setup-token</code> 生成的 token</td><td>✅</td></tr></tbody></table><p><strong>Self-managed</strong> 表示 Memoh 直接用你在 workspace 里自己维护的配置来启动智能体。</p><h3 id="codex-设备码授权" tabindex="-1">Codex 设备码授权 <a class="header-anchor" href="#codex-设备码授权" aria-label="Permalink to &quot;Codex 设备码授权&quot;">​</a></h3><p>在 Codex 设置里点 <strong>Use Device Code</strong>，Memoh 显示验证 URL 和一次性代码，你在 OpenAI 页面确认后授权自动完成。</p><blockquote><p>一次性代码只在显示的 OpenAI 验证 URL 上输入——设备码可能被用于钓鱼。</p></blockquote><h2 id="adapter-自动升级" tabindex="-1">Adapter 自动升级 <a class="header-anchor" href="#adapter-自动升级" aria-label="Permalink to &quot;Adapter 自动升级&quot;">​</a></h2><p>Codex 和 Claude Code 的 adapter 是 npm 包。Memoh 每次服务进程启动后（按 bot）解析一次 npm 上的最新版本并启动它，adapter 的修复不需要升级 Memoh 就能拿到。解析或启动失败时回退到 workspace 镜像里内置的版本，直到下次服务重启。</p><hr><h2 id="reasoning-effort" tabindex="-1">Reasoning Effort <a class="header-anchor" href="#reasoning-effort" aria-label="Permalink to &quot;Reasoning Effort&quot;">​</a></h2><p>智能体支持时，可以在 composer 的模型选择器里悬停 <strong>Reasoning</strong> 按会话选择推理力度。</p><ul><li>可选项（以及它们的名字）由外部智能体自己声明，换模型时可能变化。</li><li>未选择时的默认值：Codex 是 <code>medium</code>，Claude Code 是 <code>high</code>。</li><li>选择按会话独立，和模型选择互不影响。</li></ul><p>之前选的力度失效时，Memoh 会刷新智能体的选项并让你重选，而不是悄悄失败。</p><hr><h2 id="附件" tabindex="-1">附件 <a class="header-anchor" href="#附件" aria-label="Permalink to &quot;附件&quot;">​</a></h2><p>ACP 智能体会话支持消息附件：</p><ul><li><strong>图片</strong>：智能体声明支持图片输入时原生发送；不支持时若图片有 workspace 路径可引用，自动降级为文件引用。</li><li><strong>文件</strong>、长文本粘贴、引用/回复消息里带的附件，以 workspace 路径或公开 URL 的形式传给智能体。</li><li>可以只发附件不带文字。</li></ul><p>附件送不到智能体时会在聊天里报明确错误，不会静默丢弃。</p><hr><h2 id="默认-agent" tabindex="-1">默认 Agent <a class="header-anchor" href="#默认-agent" aria-label="Permalink to &quot;默认 Agent&quot;">​</a></h2><p>Bot 的交互设置里有 <strong>默认 Agent</strong> 下拉框——可以选 Memoh 本体，或任一已启用且配置完成的 ACP 智能体。只影响之后新建的一对一会话，已有会话和群聊 Discuss 不受影响。</p><hr><h2 id="acp-agent-会话" tabindex="-1">ACP Agent 会话 <a class="header-anchor" href="#acp-agent-会话" aria-label="Permalink to &quot;ACP Agent 会话&quot;">​</a></h2><p>ACP 工作使用 <code>acp_agent</code> 会话类型，由 Agents/ACP 工作流创建和管理，不走普通 <code>/new chat</code> / <code>/new discuss</code> 路由。客户端里可以按 <code>acp_agent</code> 过滤，把编码工作和日常对话分开看。</p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./working-with-bots.html">Bot</a></li><li><a href="./sessions.html">会话</a></li><li><a href="./files.html">文件</a></li><li><a href="./../integrations/providers/llm.html">模型服务商与模型</a></li></ul>',35)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
